def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    broccoli_patches = image_patch.find("broccoli")
    plate_patches = image_patch.find("plate")

    if not broccoli_patches or not plate_patches:
        return image_patch

    plate_center_x = sum(p.horizontal_center for p in plate_patches) / len(plate_patches)
    plate_center_y = sum(p.vertical_center for p in plate_patches) / len(plate_patches)

    clock_positions = {
        12: lambda x, y: abs(x - plate_center_x) < 10 and abs(y - plate_center_y) < 10,
        3: lambda x, y: abs(x - plate_center_x + 100) < 10 and abs(y - plate_center_y) < 10,
        6: lambda x, y: abs(x - plate_center_x) < 10 and abs(y - plate_center_y + 100) < 10,
        9: lambda x, y: abs(x - plate_center_x - 100) < 10 and abs(y - plate_center_y) < 10
    }

    for pos, condition in clock_positions.items():
        matched_broccoli = [b for b in broccoli_patches if condition(b.horizontal_center, b.vertical_center)]
        if matched_broccoli:
            return matched_broccoli[0]

    return broccoli_patches[0]

